async function writeBindings(dir:string,files:Readonly<Record<string,string>>){
 const helper=join(dir,"native-admin.ts");
 const source=await readFile(resolve(import.meta.dir,"../../mantle-admin/src/server/native.ts"),"utf8");
 const linked=Object.fromEntries(Object.entries(files).map(([name,text])=>[name,text.replaceAll('"@aotter/mantle-admin/server/native"','"./'+(name.startsWith("admin/")?"../":"")+'native-admin.js"')]));
 await writeGenerated(dir,{...linked,"native-admin.ts":source.replaceAll('"@aotter/mantle/','"@aotter/mantle/')});
}
async function fixture(){const dir=await mkdtemp(join(import.meta.dir,"apps/.admin-bindings-"));const result=await generateFromSources({target:"bun-sqlite",sources:{sources:[source]},admin:true});if(!result.ok)throw Error(JSON.stringify(result.diagnostics));await writeBindings(dir,result.files);const {adminBindings}=await import(join(dir,"admin-bindings.ts"));const db=new Database(":memory:");db.exec(result.files["schema.sql"]!);return {dir,db,files:result.files,bindings:adminBindings()};}
test("selected Admin emits factories, indexed null ordering, scoped batch filters and independent statistics branches in one round trip",async()=>{
 const {dir,db,files,bindings}=await fixture();const adapter=bindings.adapter,native=await import(join(dir,"native-admin.ts"));try{
 expect(files["admin-bindings.ts"]).toContain('import type {EntrySchema}');expect(files["admin-bindings.ts"]!.split("export function adminBindings")[0]).not.toContain("=store(");
 expect(bindings.metadata.allCollections.records.exportFields).toEqual(["label","kind","flag","data","expiry"]);expect(bindings.metadata.allCollections.records.scopeField).toBe("ownerId");
 const schema=bindings.schemas[0], now=1000000;
 db.exec(`INSERT INTO records(id,version,created_at,updated_at,status,ownerid,label,kind,flag,data) VALUES ('a',1,${now*1000},0,'draft','A',NULL,'a',1,'{"x":1}'),('b',1,${(now+1200)*1000},0,'draft','A','same','a',0,'{}'),('c',1,${(now+1200)*1000},0,'published','A','same','b',1,'{}'),('d',1,0,0,'draft','A',NULL,NULL,0,'{}'),('foreign',1,${now*1000},0,'published','B','other','a',0,'{}')`);
 db.exec(`INSERT INTO records(id,version,created_at,updated_at,status,ownerid,label,kind,expiry) VALUES ('expired',1,0,0,'published','A','ghost','a',0)`);
 const c=(q:any)=>native.nativeEntryPage(schema.binding,adapter,()=>db,caller("A"),q);
 for(const direction of ["asc","desc"]){const ids:string[]=[];let cursor:string|undefined;do{const q=schema.query(new URLSearchParams({sort:"label",direction,limit:"1",...(cursor?{cursor}:{})}));const page=await c(q);ids.push(...page.rows.map((r:any)=>r.id));cursor=page.nextCursor??undefined;}while(cursor);expect(ids).toEqual(direction==="asc"?["a","d","b","c"]:["b","c","a","d"]);}
 const filtered=await c(schema.query(new URLSearchParams({filter_field:"kind",filter_values:'["a","b"]'})));expect(filtered.rows.map((r:any)=>r.id).sort()).toEqual(["a","b","c"]);
 const row=schema.row(filtered.rows.find((r:any)=>r.id==="a"));expect(row.flag).toBe(true);expect(row.data).toEqual({x:1});expect(row.ownerId).toBeUndefined();
 expect(()=>schema.query(new URLSearchParams({filter_field:"kind",filter_values:JSON.stringify(Array(51).fill("a"))}))).toThrow();
 expect(()=>schema.query(new URLSearchParams({filter_field:"expiry",filter_value:"not-a-date"}))).toThrow();
 expect(()=>schema.query(new URLSearchParams({filter_field:"toString",filter_value:"x"}))).toThrow();
 expect(()=>schema.query(new URLSearchParams({filter_values:'["a"]'}))).toThrow();
 const {statisticsView}=await import(join(dir,"admin-bindings.ts"));let reads=0;const instrument={query:(sql:string)=>({all:(...values:unknown[])=>{reads++;return db.query(sql).all(...values as any[]);}})};
 const stats=await statisticsView(instrument,caller("A"),"records",{from:now,to:now+2000,bucketMs:1000});expect(reads).toBe(1);expect(stats).toEqual({total:4,buckets:[{bucket:0,subtype:null,count:1},{bucket:1,subtype:null,count:2}]});
 await expect(statisticsView(instrument,caller("A"),"records; DROP TABLE records",{from:now,to:now+2000,bucketMs:1000})).rejects.toThrow();await expect(statisticsView(instrument,caller("A"),"records",{from:0,to:2,bucketMs:0})).rejects.toThrow();expect(reads).toBe(1);
 const first=await c(schema.query(new URLSearchParams({sort:"label",limit:"1"})));await expect(native.nativeEntryPage(schema.binding,adapter,()=>db,caller("B"),{...schema.query(new URLSearchParams({sort:"label",limit:"1"})),cursor:first.nextCursor})).rejects.toThrow();
 await expect(c({...schema.query(new URLSearchParams({sort:"label"})),cursor:encodeCursor({},"a")})).rejects.toThrow();
 }finally{db.close();await rm(dir,{recursive:true,force:true});}
});
